<section class="erp-card"><h2>داده معاملات ماده ۱۶۹</h2><p class="erp-review-notice"><?php echo esc_html(LegalService::NOTICE); ?>؛ فایل آماده ارسال دولتی نیست.</p><?php LegalController::filters($cid,$p,$from,$to);LegalController::exportLink($cid,'transactions'); ?><p>مبالغ ریال است؛ فاکتور صادرشده و برگشت واقعی ملاک‌اند. نام و کد اقتصادی از تصویر زمان صدور، در صورت وجود، خوانده می‌شوند؛ شناسه ملی در نمایش عادی پوشیده است. داده هویتی ناقص با هشدار مشخص می‌شود.</p><div class="erp-scroll"><table class="erp-table"><thead><tr><th>نوع / شماره</th><th>تاریخ</th><th>طرف معامله</th><th>کد اقتصادی</th><th>شناسه پوشیده</th><th>مبنای هویت</th><th>خالص</th><th>مالیات</th><th>هزینه جانبی</th><th>کل</th><th>بررسی</th></tr></thead><tbody><?php foreach($d['rows'] as $r): ?><tr><td><?php echo esc_html($kinds[$r['kind']].' / '.$r['number']); ?></td><td><?php echo esc_html(Jalali::format($r['invoice_date'])); ?></td><td><?php echo esc_html($r['name']); ?></td><td><?php echo esc_html($r['economic_code']); ?></td><td><?php echo esc_html($r['national_id']); ?></td><td><?php echo $r['identity_basis']==='issued_hint'?'تصویر زمان صدور':'پرونده فعلی؛ تصویر قدیمی کامل نیست'; ?></td><?php foreach(['net','tax','extra','amount'] as $k): ?><td><?php echo esc_html(Money::fmt($r[$k])); ?></td><?php endforeach; ?><td><?php echo $r['missing_identity']?'اطلاعات هویتی کامل نیست':'نیازمند بررسی حسابدار'; ?></td></tr><?php endforeach; ?></tbody></table></div><?php self::pages($d['pages'],$d['page']); ?></section>
<?php if(Ctx::can('legal.export')&&Ctx::can('party.sensitive')): ?><section class="erp-card erp-no-print"><h3>خروجی دارای شناسه ملی آشکار</h3><p>این خروجی محرمانه است و دریافت آن در ممیزی ثبت می‌شود. شناسه کامل از پرونده فعلی شخص خوانده می‌شود؛ تضمینی برای یکسان‌بودن آن با زمان صدور وجود ندارد. فقط برای بازبینی حسابدار دریافت کنید.</p><form method="post" class="erp-form"><?php self::form('module_legal_sensitive',$cid,$p); ?><input type="hidden" name="from" value="<?php echo esc_attr(Jalali::format($from,false)); ?>"><input type="hidden" name="to" value="<?php echo esc_attr(Jalali::format($to,false)); ?>"><button class="btn btn-outline" type="submit">دریافت CSV محرمانه و ثبت در ممیزی</button></form></section><?php endif; ?>
